export interface Params {
  fruitGrowth: number;
  fruitLimit: number;
  fruitDelay: number;

  blueEnergyUse: number;
  blueSpeed: number;
  blueVision: number;
  blueCopyAt: number;
  blueEatTime: number;

  redEnergyUse: number;
  redSpeed: number;
  redVision: number;
  redContact: number;
  redCopyAt: number;
  redPauseTime: number;

  startTrees: number;
  startBlue: number;
  startRed: number;
  worldSize: number;
  seed: number;

  simSpeed: number;
  traitDrift: number;
}

export type ParamKey = keyof Params;
export type GroupId = "fruit" | "blue" | "red" | "start" | "sim";

export interface ParamMeta {
  key: ParamKey;
  label: string;
  group: GroupId;
  min: number;
  max: number;
  step: number;
  /** Changes to "start" params only take effect on reset. */
  live: boolean;
  format: (v: number) => string;
  hint: (v: number, p: Params) => string;
}

export const BASE_RIPEN_SECONDS = 10;

const fx = (d: number, suffix = "") => (v: number) => `${v.toFixed(d)}${suffix}`;

