export const META_BY_KEY = Object.fromEntries(PARAM_META.map((m) => [m.key, m])) as Record<
  ParamKey,
  ParamMeta
>;

export const DEFAULT_PARAMS: Params = {
  fruitGrowth: 1.2,
  fruitLimit: 7,
  fruitDelay: 4,

  blueEnergyUse: 1,
  blueSpeed: 1.9,
  blueVision: 4.5,
  blueCopyAt: 60,
  blueEatTime: 1.5,

  redEnergyUse: 1,
  redSpeed: 2,
  redVision: 2.4,
  redContact: 15,
  redCopyAt: 95,
  redPauseTime: 3,

  startTrees: 14,
  startBlue: 60,
  startRed: 6,
  worldSize: 18,
  seed: 7,

  simSpeed: 3,
  traitDrift: 0.03,
};

export interface Preset {
  id: string;
  name: string;
  blurb: string;
  params: Partial<Params>;
}

export const PRESETS: Preset[] = [
  {
    id: "balanced",
    name: "Balanced garden",
    blurb: "Blues and reds rise and fall in long, out-of-phase waves.",
    params: {},
  },
  {
    id: "fruit-rich",
    name: "Fruit-rich garden",
    blurb: "Fast, heavy fruit. Blues boom first, reds chase the boom.",
    params: {},
  },
  {
    id: "red-heavy",
    name: "Red-heavy garden",
    blurb: "Lots of hungry reds. Blues dip first, then reds run out of energy.",
    params: {},
  },
  {
    id: "fragile",
    name: "Fragile balance",
    blurb: "Big swings on a knife edge. One group may not make it.",
    params: {},
  },
  {
    id: "low-fruit",
    name: "Low-fruit garden",
    blurb: "Few trees, slow fruit. Everything stays small.",
    params: {},
  },
];

export function presetParams(id: string, base: Params = DEFAULT_PARAMS): Params {
  const preset = PRESETS.find((p) => p.id === id);
  return { ...DEFAULT_PARAMS, simSpeed: base.simSpeed, ...(preset?.params ?? {}) };
}

export function clampParam(key: ParamKey, v: number): number {
  const m = META_BY_KEY[key];
  if (!m) return v;
  const stepped = Math.round((v - m.min) / m.step) * m.step + m.min;
  return Math.min(m.max, Math.max(m.min, Number(stepped.toFixed(4))));
}

}

// ---------------------------------------------------------------- world build

setSim(sim: Simulation) {
  const sizeChanged = sim.R !== this.R;
  this.sim = sim;
  this.R = sim.R;
  this.vis.clear();
  this.sparkles.clear();
  this.bits.clear();
  this.buildWorld(sim);
  if (sizeChanged) this.frameCamera();
}

frameCamera() {
  const R = this.R;
  this.controls.minDistance = R * 0.55;
  this.controls.maxDistance = R * 4.2;
  const d = R * 2.55;
  const polar = 0.92;
  const az = 0.55;
  this.controls.target.set(0, 0, 0);
  this.camera.position.set(Math.sin(polar) * Math.sin(az) * d, Math.cos(polar) * d, Math.sin(polar) * Math.cos(az) * d);
  this.controls.update();
}

private buildWorld(sim: Simulation) {
  for (const d of this.worldDisposables) d.dispose();
  this.worldDisposables = [];

private updateSelection(sim: Simulation, now: number) {
  const sel = this.selectedId !== null ? sim.byId.get(this.selectedId) : undefined;
  const selVis = sel ? this.vis.get(sel.id) : undefined;
  const show = !!(sel && selVis);
  this.selRing.visible = show;
  this.marker.visible = show;
  this.senseRing.visible = show && this.settings.showSense;
  this.fearRing.visible = show && this.settings.showSense && sel?.group === "blue";
  this.targetLine.visible = false;

  if (sel && selVis) {
    const color = sel.group === "blue" ? 0x4d97ff : 0xff5a6a;
    (this.selRing.material as THREE.MeshBasicMaterial).color.setHex(color);
    const pulse = 1 + Math.sin(now * 5) * 0.06;
    this.selRing.position.set(selVis.pos.x, 0.03, selVis.pos.z);
    this.selRing.scale.setScalar(selVis.size * pulse);
    this.marker.position.set(selVis.pos.x, selVis.pos.y + 0.75 + Math.sin(now * 3) * 0.08, selVis.pos.z);
    this.marker.rotation.y = now * 2;
    const p = sim.p;
    const vision = (sel.group === "blue" ? p.blueVision : p.redVision) * sel.visionGene;
    this.senseRing.position.set(selVis.pos.x, 0.035, selVis.pos.z);
    this.senseRing.scale.setScalar(vision);
    (this.senseRing.material as THREE.MeshBasicMaterial).color.setHex(sel.group === "blue" ? 0xbfe0ff : 0xffd0d6);
    this.fearRing.position.set(selVis.pos.x, 0.036, selVis.pos.z);
    this.fearRing.scale.setScalar(vision * 0.65);

    const target = this.lookTarget(sel, sim);
    if (target && sel.action !== "fade") {
      const tv = "id" in target ? this.vis.get((target as Blob).id)?.pos : undefined;
      const tx = tv ? tv.x : target.x;
      const tz = tv ? tv.z : target.z;
      const pos = this.targetLine.geometry.attributes.position as THREE.BufferAttribute;
      pos.setXYZ(0, selVis.pos.x, 0.09, selVis.pos.z);
      pos.setXYZ(1, tx, 0.09, tz);
      pos.needsUpdate = true;
      this.targetLine.computeLineDistances();
      (this.targetLine.material as THREE.LineDashedMaterial).color.setHex(sel.group === "blue" ? 0xe6ffb0 : 0xffffff);
      this.targetLine.visible = true;
    }

    if (this.settings.follow) {
      const tgt = this.controls.target;
      _v.set(selVis.pos.x, 0, selVis.pos.z).sub(tgt).multiplyScalar(0.08);
      tgt.add(_v);
      this.camera.position.add(_v);
    }
  }

  const hov = this.hoverId !== null && this.hoverId !== this.selectedId ? this.vis.get(this.hoverId) : undefined;
  const hovBlob = this.hoverId !== null ? sim.byId.get(this.hoverId) : undefined;
  this.hoverRing.visible = !!(hov && hovBlob);
  if (hov && hovBlob) {
    (this.hoverRing.material as THREE.MeshBasicMaterial).color.setHex(hovBlob.group === "blue" ? 0xa8ceff : 0xffb0b8);
    this.hoverRing.position.set(hov.pos.x, 0.03, hov.pos.z);
    this.hoverRing.scale.setScalar(hov.size);
  }
}

// ---------------------------------------------------------------- events → particles

import type { Sample } from "./engine";

export function smooth(values: number[], window: number): number[] {
  if (window <= 1) return values.slice();
  const half = Math.floor(window / 2);
  const out = new Array<number>(values.length);
  let sum = 0;
  let count = 0;
  let lo = 0;
  let hi = -1;
  for (let i = 0; i < values.length; i++) {
    const wantLo = Math.max(0, i - half);
    const wantHi = Math.min(values.length - 1, i + half);
    while (hi < wantHi) {
      hi++;
      sum += values[hi];
      count++;
    }
    while (lo < wantLo) {
      sum -= values[lo];
      lo++;
      count--;
    }
    out[i] = sum / count;
  }
  return out;
}

export interface Peak {
  index: number;
  value: number;
}

/** Local maxima whose prominence (drop to the lower neighbouring trough) is at least `minProminence`. */
export function findPeaks(values: number[], minProminence: number): Peak[] {
  const peaks: Peak[] = [];
  const n = values.length;
  if (n < 3) return peaks;
  let lastTrough = values[0];
  let candidate = -1;
  let candidateValue = -Infinity;
  let rising = false;
  for (let i = 1; i < n; i++) {
    const v = values[i];
    if (!rising) {
      if (v < lastTrough) lastTrough = v;
      if (v - lastTrough >= minProminence) {
        rising = true;
        candidate = i;
        candidateValue = v;
      }
    } else {
      if (v > candidateValue) {
        candidateValue = v;
        candidate = i;
      }
      if (candidateValue - v >= minProminence) {
        peaks.push({ index: candidate, value: candidateValue });
        rising = false;
        lastTrough = v;
      }
    }
  }
  return peaks;
}

/** Lag (in samples) at which `lead` best predicts `follow`; positive means `follow` trails `lead`. */
export function bestLag(lead: number[], follow: number[], maxLag: number) {
  const n = Math.min(lead.length, follow.length);
  let best = 0;
  let bestCorr = -Infinity;
  for (let lag = 0; lag <= maxLag; lag++) {
    const m = n - lag;
    if (m < 20) break;
    let ma = 0;
    let mb = 0;
    for (let i = 0; i < m; i++) {
      ma += lead[i];
      mb += follow[i + lag];
    }
    ma /= m;
    mb /= m;
    let num = 0;
    let da = 0;
    let db = 0;
    for (let i = 0; i < m; i++) {
      const a = lead[i] - ma;
      const b = follow[i + lag] - mb;
      num += a * b;
      da += a * a;
      db += b * b;
    }
    const corr = da > 0 && db > 0 ? num / Math.sqrt(da * db) : 0;
    if (corr > bestCorr) {
      bestCorr = corr;
      best = lag;
    }
  }
  return { lag: best, corr: bestCorr };
}

export function stats(values: number[]) {
  if (!values.length) return { mean: 0, min: 0, max: 0, sd: 0, cv: 0 };
  let sum = 0;
  let min = Infinity;
  let max = -Infinity;
  for (const v of values) {
    sum += v;
    if (v < min) min = v;
    if (v > max) max = v;
  }
  const mean = sum / values.length;
  let sq = 0;
  for (const v of values) sq += (v - mean) * (v - mean);
  const sd = Math.sqrt(sq / values.length);
  return { mean, min, max, sd, cv: mean > 0 ? sd / mean : 0 };
}

export interface WaveReport {
  bluePeaks: Peak[];
  redPeaks: Peak[];
  /** Red peaks that trail a blue peak, i.e. completed predator-prey waves. */
  pairedWaves: number;
  meanLagSeconds: number | null;
  periodSeconds: number | null;
  dt: number;
}

export function waveReport(history: Sample[]): WaveReport {
  const dt = history.length > 1 ? (history[history.length - 1].t - history[0].t) / (history.length - 1) : 1;
  const w = Math.max(3, Math.round(9 / dt));
  const blue = smooth(
    history.map((s) => s.blue),
    w,
  );
  const red = smooth(
    history.map((s) => s.red),
    w,
  );
  const bs = stats(blue);
  const rs = stats(red);
  const bluePeaks = findPeaks(blue, Math.max(3, (bs.max - bs.min) * 0.18, bs.mean * 0.15));
  const redPeaks = findPeaks(red, Math.max(1.5, (rs.max - rs.min) * 0.18, rs.mean * 0.15));

  const lags: number[] = [];
  let bi = 0;
  for (const rp of redPeaks) {
    while (bi + 1 < bluePeaks.length && bluePeaks[bi + 1].index < rp.index) bi++;
    const bp = bluePeaks[bi];
    if (!bp || bp.index >= rp.index) continue;
    const lag = (rp.index - bp.index) * dt;
    if (lag < 400) lags.push(lag);
  }
  let period: number | null = null;
  if (bluePeaks.length >= 2) {
    period = ((bluePeaks[bluePeaks.length - 1].index - bluePeaks[0].index) * dt) / (bluePeaks.length - 1);
  }
  return {
    bluePeaks,
    redPeaks,
    pairedWaves: lags.length,
    meanLagSeconds: lags.length ? lags.reduce((a, b) => a + b, 0) / lags.length : null,
    periodSeconds: period,
    dt,
  };
}

export class Simulation {
  p: Params;
  readonly seed: number;
  readonly R: number;
  time = 0;
  trees: Tree[] = [];
  blobs: Blob[] = [];
  byId = new Map<number, Blob>();
  history: Sample[] = [];
  events: SimEvent[] = [];
  recordEvents = false;
  extinctAt: { blue: number | null; red: number | null } = { blue: null, red: null };
  peakBlue = 0;
  peakRed = 0;
  totals = zeroCounters();
  chases = 0;
  caughtWhile: Partial<Record<Action, number>> = {};

  private rng: Rng;
  private nextId = 1;
  private blueGrid: Grid;
  private redGrid: Grid;
  private counters = zeroCounters();
  private sampleClock = 0;
  private sampleStride = 1;
  private pendingStride = 0;
  private hadRemoval = false;

  constructor(params: Params) {
    this.p = { ...params };
    this.seed = params.seed;
    this.R = params.worldSize;
    this.rng = mulberry32((params.seed * 9973 + 12345) >>> 0);
    this.blueGrid = new Grid(this.R, 1.6);
    this.redGrid = new Grid(this.R, 1.6);
    this.setup();
  }

  setParams(p: Params) {
    this.p = p;
  }

  // ---------------------------------------------------------------- setup

  private randomInDisk(maxR: number) {
    const r = Math.sqrt(this.rng()) * maxR;
    const a = this.rng() * TAU;
    return { x: Math.cos(a) * r, z: Math.sin(a) * r };
  }

  return b;
}

// ---------------------------------------------------------------- stepping

advance(seconds: number) {
  const steps = Math.max(1, Math.round(seconds / DT));
  for (let i = 0; i < steps; i++) this.step();
}

step(dt = DT) {
  this.time += dt;

}

// ---------------------------------------------------------------- history

counts() {
  let blue = 0;
  let red = 0;
  for (const b of this.blobs) {
    if (b.action === "fade" || b.dead) continue;
    if (b.group === "blue") blue++;
    else red++;
  }
  return { blue, red };
}

ripeFruit() {
  let n = 0;
  for (const t of this.trees) n += t.ripe;
  return n;
}

fruitCapacity() {
  return this.trees.length * Math.round(this.p.fruitLimit);
}

private record() {
  let blue = 0;
  let red = 0;
  let be = 0;
  let re = 0;
  let bs = 0;
  let bv = 0;
  let rs = 0;
  let rv = 0;
  for (const b of this.blobs) {
    if (b.action === "fade" || b.dead) continue;
    if (b.group === "blue") {
      blue++;
      be += b.energy;
      bs += b.speedGene;
      bv += b.visionGene;
    } else {
      red++;
      re += b.energy;
      rs += b.speedGene;
      rv += b.visionGene;
    }
  }
  const last = this.history[this.history.length - 1];
  const s: Sample = {
    t: Math.round(this.time * 1000) / 1000,
    fruit: this.ripeFruit(),
    blue,
    red,
    blueEnergy: blue ? be / blue : 0,
    redEnergy: red ? re / red : 0,
    blueSpeedGene: blue ? bs / blue : (last?.blueSpeedGene ?? 1),
    blueVisionGene: blue ? bv / blue : (last?.blueVisionGene ?? 1),
    redSpeedGene: red ? rs / red : (last?.redSpeedGene ?? 1),
    redVisionGene: red ? rv / red : (last?.redVisionGene ?? 1),
    ...this.counters,
  };
  this.counters = zeroCounters();

  if (blue > this.peakBlue) this.peakBlue = blue;
  if (red > this.peakRed) this.peakRed = red;
  if (last) {
    if (blue === 0 && last.blue > 0 && this.extinctAt.blue === null) this.extinctAt.blue = s.t;
    if (red === 0 && last.red > 0 && this.extinctAt.red === null) this.extinctAt.red = s.t;
  }

  if (this.sampleStride > 1 && last) {
    this.pendingStride++;
    if (this.pendingStride < this.sampleStride) {
      last.blueBirths += s.blueBirths;
      last.redBirths += s.redBirths;
      last.blueHugFades += s.blueHugFades;
      last.blueHungerFades += s.blueHungerFades;
      last.redHungerFades += s.redHungerFades;
      last.fruitEaten += s.fruitEaten;
      last.hugs += s.hugs;
      return;
    }
    this.pendingStride = 0;
  }
  this.history.push(s);

  if (this.history.length > MAX_HISTORY) {
    const merged: Sample[] = [];
    for (let i = 0; i < this.history.length; i += 2) {
      const a = this.history[i];
      const b = this.history[i + 1];
      if (b) {
        a.blueBirths += b.blueBirths;
        a.redBirths += b.redBirths;
        a.blueHugFades += b.blueHugFades;
        a.blueHungerFades += b.blueHungerFades;
        a.redHungerFades += b.redHungerFades;
        a.fruitEaten += b.fruitEaten;
        a.hugs += b.hugs;

