    this.shines = instanced(new THREE.SphereGeometry(1, 8, 6), new THREE.MeshBasicMaterial({ color: 0xffffff }), MAX_INST * 2);
    this.mouths = instanced(
      new THREE.TorusGeometry(1, 0.28, 8, 20, Math.PI),
