          for (let i = 0; i < n; i++) {
            this.sparkles.stream(
              { x: from.x + (Math.random() - 0.5) * 0.35, y: from.y + Math.random() * 0.3, z: from.z + (Math.random() - 0.5) * 0.35 },
              to,
              0.45 + i * 0.035,
              0.17,
              i % 3 === 0 ? "#ffffff" : "#6fb2ff",
