    this.sun = sun;
    const fill = new THREE.DirectionalLight(0xcfe0ff, 0.55);
    fill.position.set(-20, 14, -18);
    this.scene.add(fill);

    const bodyMat = new THREE.MeshPhysicalMaterial({
      color: 0xffffff,
      roughness: 0.26,
      metalness: 0,
      clearcoat: 1,
      clearcoatRoughness: 0.1,
      sheen: 0.3,
      sheenColor: new THREE.Color(0xffffff),
