      const inv = 1 / Math.sqrt(sy);
      _body.compose(_v.set(x, y, z), _q, _s.set(s * sx * inv, s * sy, s * inv));
      this.body.setMatrixAt(i, _body);
      v.pos.set(x, y + BODY_H * 0.5 * s, z);
