    );
    for (const o of [this.selRing, this.hoverRing, this.senseRing, this.fearRing, this.marker, this.targetLine]) {
      o.visible = false;
      o.renderOrder = 5;
      this.scene.add(o);
    }

    const baseShadow = new THREE.Mesh(
