    radial-gradient(70% 60% at 50% 38%, #fffdf7 0%, #f7eedd 60%, #efe1c7 100%);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  min-height: 0;
}

.world-canvas {
  position: absolute;
  inset: 0;
}

.world-canvas canvas {
  display: block;
}

.world-hint {
  position: absolute;
  left: 14px;
  bottom: 12px;
  color: var(--muted);
  font-weight: 650;
  font-size: 12px;
  pointer-events: none;
}

.world-toggles {
  position: absolute;
  right: 12px;
  bottom: 10px;
  display: flex;
  gap: 8px;
  align-items: center;
}

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 650;
  cursor: pointer;
  user-select: none;
}

.toggle input {
  accent-color: var(--ink);
}

.paused-pill {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(59, 48, 41, 0.85);
  color: #fff;
  padding: 4px 14px;
  border-radius: 999px;
  font-weight: 750;
  pointer-events: none;
}

.paused-pill.lag {
  background: rgba(164, 88, 30, 0.85);
  font-size: 11.5px;
}

/* ------------------------------------------------------------ inspector */

.inspector {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 262px;
  background: rgba(255, 250, 241, 0.94);
  backdrop-filter: blur(10px);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 12px 14px;
  box-shadow: 0 16px 40px -18px rgba(70, 40, 20, 0.45);
  animation: pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes pop {
  from {
    transform: scale(0.9);
    opacity: 0;
  }
}

.inspector header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.inspector h3 {
  margin: 0;
  font-size: 16px;
}

.inspector small {
  color: var(--muted);
  font-weight: 650;
}

.inspector .icon {
  margin-left: auto;
  width: 28px;
  height: 28px;
  padding: 0;
  font-size: 18px;
  line-height: 1;
  box-shadow: none;
}

.dot {
  width: 22px;
  height: 26px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  box-shadow: inset -3px -4px 0 rgba(0, 0, 0, 0.12), inset 3px 3px 0 rgba(255, 255, 255, 0.35);
}

.dot.blue {
  background: var(--blue);
}

.dot.red {
  background: var(--red);
}

.action-line {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.badge {
  font-weight: 750;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--blue-soft);
  color: #1f5fc0;
}

.inspector.red .badge {
  background: var(--red-soft);
  color: #c02a3b;
}

.time-left {
  color: var(--muted);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.progress,
.bar {
  height: 6px;
  border-radius: 999px;
  background: rgba(92, 70, 48, 0.1);
  overflow: hidden;
  margin-top: 6px;
}

.progress i,
.bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--ink);
}

.bar {
  height: 9px;
}

.inspector.blue .bar i {
  background: linear-gradient(90deg, #7fb6ff, var(--blue));
}

.inspector.red .bar i {
  background: linear-gradient(90deg, #ff9aa4, var(--red));
}

.energy {
  margin-top: 10px;
}

.energy-label {
  display: flex;
  justify-content: space-between;
  font-weight: 650;
}

.energy-label b {
  font-variant-numeric: tabular-nums;
}

.facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin: 12px 0 10px;
}

.facts dt {
  color: var(--muted);
  font-weight: 650;
}

.facts dd {
  margin: 0;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.inspector-actions {
  display: flex;
  gap: 14px;
  border-top: 1px solid var(--line);
  padding-top: 9px;
}

/* ------------------------------------------------------------ dock */

.dock {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 0.95fr) minmax(0, 1.15fr);
  gap: 12px;
  min-height: 0;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.card-head h2 {
  margin: 0;
  font-size: 13.5px;
  font-weight: 800;
}

.card-sub {
  color: var(--muted);
  font-size: 11px;
}

.legend {
  display: flex;
  gap: 5px;
  margin-right: auto;
}

.chip {
  font-size: 11.5px;
  font-weight: 750;
  padding: 2px 9px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
}

.chip.fruit {
  background: var(--fruit-soft);
  color: #587c0c;
}

.chip.blue {
  background: var(--blue-soft);
  color: #1f5fc0;
}

.chip.red {
  background: var(--red-soft);
  color: #c02a3b;
}

.chip.ghost {
  color: var(--muted);
}

.seg {
  display: inline-flex;
  background: rgba(92, 70, 48, 0.07);
  border-radius: 999px;
  padding: 2px;
}

.seg button {
  border: none;
  background: transparent;
  box-shadow: none;
  padding: 3px 10px;
  font-size: 11.5px;
  color: var(--muted);
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(60, 40, 20, 0.15);
}

.axis-notes {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
  padding: 0 2px;
}

.axis-notes .fruit-note {
  color: var(--fruit);
}

.canvas-box {
  position: relative;
  flex: 1;
  min-height: 0;
}

.canvas-box canvas {
  position: absolute;
  inset: 0;
}

.story-list {
  list-style: none;
  margin: 0;
  padding: 0 2px 0 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 7px;
  line-height: 1.42;
}

.story-list li {
  padding-left: 12px;
  position: relative;
}

.story-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5em;
  width: 6px;
  height: 7px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  background: var(--muted);
}

.tone-blue::before {
  background: var(--blue) !important;
}

.tone-red::before {
  background: var(--red) !important;
}

.tone-fruit::before {
  background: #a6d33a !important;
  border-radius: 50% !important;
}

.traits {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
  gap: 6px;
  overflow-y: auto;
}

.traits-canvas {
  flex: 0 0 110px;
}

.trait-rows {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 3px;
}

.trait-rows li {
  display: grid;
  grid-template-columns: 1fr auto 70px;
  gap: 8px;
  font-variant-numeric: tabular-nums;
}

.trait-rows li span {
  font-weight: 650;
}

.trait-rows li.tone-blue span {
  color: #1f5fc0;
}

.trait-rows li.tone-red span {
  color: #c02a3b;
}

.trait-rows em {
  font-style: normal;
  color: var(--muted);
  text-align: right;
}

.trait-rows em.up {
  color: #3f8a17;
}

.trait-rows em.down {
  color: #b5541e;
}

.fine {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
  margin: 2px 0 0;
}

@media (max-width: 1180px) {
  .body {
    grid-template-columns: 1fr;
    overflow-y: auto;
  }

  .sidebar {
    overflow: visible;
  }

  .main {
    padding: 0 12px 12px;
    grid-template-rows: 520px auto;
  }

  .dock {
    grid-template-columns: 1fr;
    grid-auto-rows: 260px;
  }

  .stats {
    margin-left: 0;
  }
}

