.trait-rows li.tone-red span {
  color: #c02a3b;
}

.trait-rows em {
  font-style: normal;
  color: var(--muted);
  text-align: right;
}

.trait-rows em.up {
  color: #3f8a17;
}

.trait-rows em.down {
  color: #b5541e;
}

.fine {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
  margin: 2px 0 0;
}

@media (max-width: 1180px) {
  .body {
    grid-template-columns: 1fr;
    overflow-y: auto;
  }

  .sidebar {
    overflow: visible;
  }

  .main {
    padding: 0 12px 12px;
    grid-template-rows: 520px auto;
  }

  .dock {
    grid-template-columns: 1fr;
    grid-auto-rows: 260px;
  }

