  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--line);
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  min-width: 58px;
  justify-content: center;
}

.stat i {
  width: 10px;
  height: 12px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
}

.stat.fruit i {
  background: #b8e04a;
  border-radius: 50%;
  width: 10px;
  height: 10px;
}

.stat.blue i {
  background: var(--blue);
}

.stat.red i {
  background: var(--red);
}

.stat.time {
  color: var(--muted);
}

.body {
  display: grid;
  grid-template-columns: 300px 1fr;
  min-height: 0;
}

.main {
  display: grid;
  grid-template-rows: minmax(340px, 1fr) 290px;
  min-height: 0;
  min-width: 0;
  padding: 12px 14px 14px 0;
  gap: 12px;
}

/* ------------------------------------------------------------ sidebar */

.sidebar {
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
  box-shadow: var(--shadow);
}

.panel h2 {
  margin: 0 0 8px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.preset {
  padding: 5px 11px;
  font-size: 12px;
  box-shadow: none;
}

.preset.on {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.blurb {
  margin: 10px 0 0;
  color: var(--muted);
  line-height: 1.4;
}

.group-head {
  all: unset;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  cursor: pointer;
  font-weight: 750;
  font-size: 13.5px;
}

.group-head .caret {
  margin-left: auto;
  color: var(--muted);
  font-size: 16px;
}

.swatch {
  width: 12px;
  height: 14px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
}

.swatch.fruit {
  background: #b8e04a;
  border-radius: 50%;
  height: 12px;
}

.swatch.blue {
  background: var(--blue);
}

.swatch.red {
  background: var(--red);
}

.swatch.start {
  background: var(--clay);
  border-radius: 4px;
  height: 12px;
}

.swatch.sim {
  background: var(--muted);
  border-radius: 50%;
  height: 12px;
}

.pending-badge {
  font-size: 10.5px;
  font-weight: 750;
  color: #a4581e;
  background: #ffe9cf;
  padding: 2px 8px;
  border-radius: 999px;
}

.params {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
}

.param {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.param-head {
  display: flex;
  justify-content: space-between;
  font-weight: 650;
}

.param-head output {
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.param.pending .param-head output {
  color: #a4581e;
}

.param .hint {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.2s ease;
}

.param:hover .hint,
.param:focus-within .hint {
  max-height: 40px;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--ink);
  height: 18px;
  margin: 0;
}

.group-fruit input[type="range"] {
  accent-color: var(--fruit);
}

.group-blue input[type="range"] {
  accent-color: var(--blue);
}

.group-red input[type="range"] {
  accent-color: var(--red);
}

.group-start input[type="range"] {
  accent-color: var(--clay);
}

.seed-row {
  display: flex;
  gap: 6px;
  align-items: center;
}

.seed-row input {
  flex: 1;
  min-width: 0;
  font: inherit;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: #fff;
}

/* ------------------------------------------------------------ world */

.world {
  position: relative;
  border-radius: 22px;
  overflow: hidden;
  background:
    radial-gradient(70% 60% at 50% 38%, #fffdf7 0%, #f7eedd 60%, #efe1c7 100%);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  min-height: 0;
}

.world-canvas {
  position: absolute;
  inset: 0;
}

.world-canvas canvas {
  display: block;
}

.world-hint {
  position: absolute;
  left: 14px;
  bottom: 12px;
  color: var(--muted);
  font-weight: 650;
  font-size: 12px;
  pointer-events: none;
}

.world-toggles {
  position: absolute;
  right: 12px;
  bottom: 10px;
  display: flex;
  gap: 8px;
  align-items: center;
}

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 650;
  cursor: pointer;
  user-select: none;
}

.toggle input {
  accent-color: var(--ink);
}

.paused-pill {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(59, 48, 41, 0.85);
  color: #fff;
  padding: 4px 14px;
  border-radius: 999px;
  font-weight: 750;
  pointer-events: none;
}

.paused-pill.lag {
  background: rgba(164, 88, 30, 0.85);
  font-size: 11.5px;
}

/* ------------------------------------------------------------ inspector */

.inspector {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 262px;
  background: rgba(255, 250, 241, 0.94);
  backdrop-filter: blur(10px);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 12px 14px;
  box-shadow: 0 16px 40px -18px rgba(70, 40, 20, 0.45);
  animation: pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes pop {
  from {
    transform: scale(0.9);
    opacity: 0;
  }
}

.inspector header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.inspector h3 {
  margin: 0;
  font-size: 16px;
}

.inspector small {
  color: var(--muted);
  font-weight: 650;
}

.inspector .icon {
  margin-left: auto;
  width: 28px;
  height: 28px;
  padding: 0;
  font-size: 18px;
  line-height: 1;
  box-shadow: none;
