.dot {
  width: 22px;
  height: 26px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  box-shadow: inset -3px -4px 0 rgba(0, 0, 0, 0.12), inset 3px 3px 0 rgba(255, 255, 255, 0.35);
}

.dot.blue {
  background: var(--blue);
}

.dot.red {
  background: var(--red);
}

.action-line {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.badge {
  font-weight: 750;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--blue-soft);
  color: #1f5fc0;
}

.inspector.red .badge {
  background: var(--red-soft);
  color: #c02a3b;
}

.time-left {
  color: var(--muted);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.progress,
.bar {
  height: 6px;
  border-radius: 999px;
  background: rgba(92, 70, 48, 0.1);
  overflow: hidden;
  margin-top: 6px;
