.bar {
  height: 9px;
}

.inspector.blue .bar i {
  background: linear-gradient(90deg, #7fb6ff, var(--blue));
}

.inspector.red .bar i {
  background: linear-gradient(90deg, #ff9aa4, var(--red));
}

.energy {
  margin-top: 10px;
}

.energy-label {
  display: flex;
  justify-content: space-between;
  font-weight: 650;
}

.energy-label b {
  font-variant-numeric: tabular-nums;
}

.facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin: 12px 0 10px;
}

.facts dt {
  color: var(--muted);
  font-weight: 650;
}

.facts dd {
  margin: 0;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
