.dock {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 0.95fr) minmax(0, 1.15fr);
  gap: 12px;
  min-height: 0;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

.card-head {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.card-head h2 {
  margin: 0;
  font-size: 13.5px;
  font-weight: 800;
}

.card-sub {
  color: var(--muted);
  font-size: 11px;
}

.legend {
  display: flex;
  gap: 5px;
  margin-right: auto;
}

.chip {
  font-size: 11.5px;
  font-weight: 750;
  padding: 2px 9px;
  border-radius: 999px;
  font-variant-numeric: tabular-nums;
}

.chip.fruit {
  background: var(--fruit-soft);
  color: #587c0c;
}

.chip.blue {
  background: var(--blue-soft);
  color: #1f5fc0;
}

.chip.red {
  background: var(--red-soft);
  color: #c02a3b;
}

.chip.ghost {
  color: var(--muted);
}

.seg {
  display: inline-flex;
  background: rgba(92, 70, 48, 0.07);
  border-radius: 999px;
  padding: 2px;
}

.seg button {
  border: none;
  background: transparent;
  box-shadow: none;
  padding: 3px 10px;
  font-size: 11.5px;
  color: var(--muted);
}

.seg button.on {
  background: #fff;
  color: var(--ink);
  box-shadow: 0 1px 3px rgba(60, 40, 20, 0.15);
}

.axis-notes {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: var(--muted);
  padding: 0 2px;
}

.axis-notes .fruit-note {
  color: var(--fruit);
}

.canvas-box {
  position: relative;
  flex: 1;
  min-height: 0;
}

.canvas-box canvas {
  position: absolute;
  inset: 0;
}

.story-list {
  list-style: none;
  margin: 0;
  padding: 0 2px 0 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 7px;
  line-height: 1.42;
}

.story-list li {
  padding-left: 12px;
  position: relative;
}

.story-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5em;
  width: 6px;
  height: 7px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  background: var(--muted);
}

.tone-blue::before {
  background: var(--blue) !important;
}

.tone-red::before {
  background: var(--red) !important;
}

.tone-fruit::before {
  background: #a6d33a !important;
  border-radius: 50% !important;
}

.traits {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
  gap: 6px;
  overflow-y: auto;
}

.traits-canvas {
  flex: 0 0 110px;
}

.trait-rows {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 3px;
}

.trait-rows li {
  display: grid;
  grid-template-columns: 1fr auto 70px;
  gap: 8px;
  font-variant-numeric: tabular-nums;
}

.trait-rows li span {
  font-weight: 650;
}

.trait-rows li.tone-blue span {
  color: #1f5fc0;
}

.trait-rows li.tone-red span {
  color: #c02a3b;
}

.trait-rows em {
  font-style: normal;
  color: var(--muted);
  text-align: right;
}

.trait-rows em.up {
  color: #3f8a17;
}

.trait-rows em.down {
  color: #b5541e;
}

.fine {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
  margin: 2px 0 0;
}

@media (max-width: 1180px) {
  .body {
    grid-template-columns: 1fr;
    overflow-y: auto;
  }

  .sidebar {
    overflow: visible;
  }

  .main {
    order: -1;
    padding: 12px 12px 0;
    grid-template-rows: 520px auto;
  }

  .dock {
    grid-template-columns: 1fr;
    grid-auto-rows: 260px;
  }

  .stats {
    margin-left: 0;
  }
}

