:root {
  --bg: #f6efe2;
  --bg-deep: #efe4d0;
  --card: #fffaf1;
  --ink: #3b3029;
  --muted: #9a8b7c;
  --line: rgba(92, 70, 48, 0.12);
  --blue: #3b8cff;
  --blue-soft: #e3efff;
  --red: #ff5a6a;
  --red-soft: #ffe6e8;
  --fruit: #86b81f;
  --fruit-soft: #eef7d6;
  --clay: #d9825b;
  --radius: 16px;
  --shadow: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 6px 18px -8px rgba(92, 60, 30, 0.25);
  --font: ui-rounded, "SF Pro Rounded", "Nunito", "Quicksand", system-ui, -apple-system, "Segoe UI", sans-serif;
  color-scheme: light;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: radial-gradient(1200px 700px at 60% 20%, #fbf6ec 0%, var(--bg) 55%, var(--bg-deep) 100%);
  color: var(--ink);
  font-family: var(--font);
  font-size: 13px;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  border: 1px solid var(--line);
  background: var(--card);
  border-radius: 999px;
  padding: 6px 14px;
  font-weight: 650;
  box-shadow: var(--shadow);
  transition:
    transform 0.12s ease,
    background 0.15s ease,
    box-shadow 0.15s ease;
}

button:hover:not(:disabled) {
  transform: translateY(-1px);
}

button:active:not(:disabled) {
  transform: translateY(1px) scale(0.98);
}

button:disabled {
  opacity: 0.45;
  cursor: default;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--blue);
  outline-offset: 2px;
}

button.primary {
  background: linear-gradient(180deg, #4f9bff, #2f7cf0);
  color: #fff;
  border-color: #2a6fd8;
}

button.ghost {
  background: transparent;
  box-shadow: none;
}

button.small {
  padding: 4px 10px;
  font-size: 12px;
}

/* ------------------------------------------------------------ layout */

.app {
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100%;
  min-height: 0;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 10px 18px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 250, 241, 0.7);
  backdrop-filter: blur(8px);
  flex-wrap: wrap;
}

.topbar h1 {
  margin: 0;
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -0.01em;
}

.transport {
  display: flex;
  gap: 8px;
}

.transport .primary {
  min-width: 76px;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-weight: 650;
}

.speed input {
  width: 140px;
}

.speed output {
  min-width: 48px;
  color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.stats {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.stat {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 999px;
  background: var(--card);
  border: 1px solid var(--line);
  font-weight: 750;
  font-variant-numeric: tabular-nums;
  min-width: 58px;
  justify-content: center;
}

.stat i {
  width: 10px;
  height: 12px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
}

.stat.fruit i {
  background: #b8e04a;
  border-radius: 50%;
  width: 10px;
  height: 10px;
}

.stat.blue i {
  background: var(--blue);
}

.stat.red i {
  background: var(--red);
}

.stat.time {
  color: var(--muted);
}

.body {
  display: grid;
  grid-template-columns: 300px 1fr;
  min-height: 0;
}

.main {
  display: grid;
  grid-template-rows: minmax(340px, 1fr) 290px;
  min-height: 0;
  min-width: 0;
  padding: 12px 14px 14px 0;
  gap: 12px;
}

/* ------------------------------------------------------------ sidebar */

.sidebar {
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
  box-shadow: var(--shadow);
}

.panel h2 {
  margin: 0 0 8px;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--muted);
}

.presets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.preset {
  padding: 5px 11px;
  font-size: 12px;
  box-shadow: none;
}

.preset.on {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.blurb {
  margin: 10px 0 0;
  color: var(--muted);
  line-height: 1.4;
}

.group-head {
  all: unset;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  cursor: pointer;
  font-weight: 750;
  font-size: 13.5px;
}

.group-head .caret {
  margin-left: auto;
  color: var(--muted);
  font-size: 16px;
}

.swatch {
  width: 12px;
  height: 14px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
}

.swatch.fruit {
  background: #b8e04a;
  border-radius: 50%;
  height: 12px;
}

.swatch.blue {
  background: var(--blue);
}

.swatch.red {
  background: var(--red);
}

.swatch.start {
  background: var(--clay);
  border-radius: 4px;
  height: 12px;
}

.swatch.sim {
  background: var(--muted);
  border-radius: 50%;
  height: 12px;
}

.pending-badge {
  font-size: 10.5px;
  font-weight: 750;
  color: #a4581e;
  background: #ffe9cf;
  padding: 2px 8px;
  border-radius: 999px;
}

.params {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
}

.param {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.param-head {
  display: flex;
  justify-content: space-between;
  font-weight: 650;
}

.param-head output {
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

.param.pending .param-head output {
  color: #a4581e;
}

.param .hint {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.2s ease;
}

.param:hover .hint,
.param:focus-within .hint {
  max-height: 40px;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--ink);
  height: 18px;
  margin: 0;
}

.group-fruit input[type="range"] {
  accent-color: var(--fruit);
}

.group-blue input[type="range"] {
  accent-color: var(--blue);
}

.group-red input[type="range"] {
  accent-color: var(--red);
}

.group-start input[type="range"] {
  accent-color: var(--clay);
}

.seed-row {
  display: flex;
  gap: 6px;
  align-items: center;
}

.seed-row input {
  flex: 1;
  min-width: 0;
  font: inherit;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: #fff;
}

/* ------------------------------------------------------------ world */

.world {
  position: relative;
  border-radius: 22px;
  overflow: hidden;
  background:
    radial-gradient(70% 60% at 50% 38%, #fffdf7 0%, #f7eedd 60%, #efe1c7 100%);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  min-height: 0;
}

.world-canvas {
  position: absolute;
  inset: 0;
}

.world-canvas canvas {
  display: block;
}

.world-hint {
  position: absolute;
  left: 14px;
  bottom: 12px;
  color: var(--muted);
  font-weight: 650;
  font-size: 12px;
  pointer-events: none;
}

.world-toggles {
  position: absolute;
  right: 12px;
  bottom: 10px;
  display: flex;
  gap: 8px;
  align-items: center;
}

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 650;
  cursor: pointer;
  user-select: none;
}

.toggle input {
