  background: rgba(59, 48, 41, 0.85);
  color: #fff;
  padding: 4px 14px;
  border-radius: 999px;
  font-weight: 750;
  pointer-events: none;
}

.paused-pill.lag {
  background: rgba(164, 88, 30, 0.85);
  font-size: 11.5px;
}

