  top: 12px;
  right: 12px;
  width: 262px;
  background: rgba(255, 250, 241, 0.94);
  backdrop-filter: blur(10px);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 12px 14px;
  box-shadow: 0 16px 40px -18px rgba(70, 40, 20, 0.45);
  animation: pop 0.22s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes pop {
  from {
    transform: scale(0.9);
    opacity: 0;
  }
}

.inspector header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.inspector h3 {
  margin: 0;
  font-size: 16px;
}

.inspector small {
  color: var(--muted);
  font-weight: 650;
}

.inspector .icon {
