  height: 26px;
  border-radius: 50% 50% 46% 46% / 58% 58% 42% 42%;
  box-shadow: inset -3px -4px 0 rgba(0, 0, 0, 0.12), inset 3px 3px 0 rgba(255, 255, 255, 0.35);
}

.dot.blue {
  background: var(--blue);
}

.dot.red {
  background: var(--red);
}

.action-line {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
}

.badge {
  font-weight: 750;
  padding: 3px 10px;
  border-radius: 999px;
  background: var(--blue-soft);
  color: #1f5fc0;
}

.inspector.red .badge {
  background: var(--red-soft);
  color: #c02a3b;
}

.time-left {
  color: var(--muted);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.progress,
.bar {
  height: 6px;
  border-radius: 999px;
  background: rgba(92, 70, 48, 0.1);
  overflow: hidden;
  margin-top: 6px;
}

.progress i,
.bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--ink);
}

.bar {
  height: 9px;
}

.inspector.blue .bar i {
  background: linear-gradient(90deg, #7fb6ff, var(--blue));
}

.inspector.red .bar i {
  background: linear-gradient(90deg, #ff9aa4, var(--red));
}

.energy {
  margin-top: 10px;
}

.energy-label {
  display: flex;
  justify-content: space-between;
  font-weight: 650;
}

.energy-label b {
  font-variant-numeric: tabular-nums;
}

.facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  margin: 12px 0 10px;
}

.facts dt {
  color: var(--muted);
  font-weight: 650;
}

.facts dd {
  margin: 0;
  text-align: right;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.inspector-actions {
  display: flex;
  gap: 14px;
  border-top: 1px solid var(--line);
  padding-top: 9px;
}

/* ------------------------------------------------------------ dock */

.dock {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 0.95fr) minmax(0, 1.15fr);
  gap: 12px;
  min-height: 0;
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
