}

.swatch.fruit {
  background: #b8e04a;
  border-radius: 50%;
  height: 12px;
}

.swatch.blue {
  background: var(--blue);
}

.swatch.red {
  background: var(--red);
}

.swatch.start {
  background: var(--clay);
