  height: 12px;
}

.swatch.sim {
  background: var(--muted);
  border-radius: 50%;
  height: 12px;
}

.pending-badge {
  font-size: 10.5px;
  font-weight: 750;
  color: #a4581e;
  background: #ffe9cf;
  padding: 2px 8px;
  border-radius: 999px;
}

.params {
  display: flex;
