}

.group-fruit input[type="range"] {
  accent-color: var(--fruit);
}

.group-blue input[type="range"] {
  accent-color: var(--blue);
}

.group-red input[type="range"] {
  accent-color: var(--red);
}

.group-start input[type="range"] {
  accent-color: var(--clay);
}

.seed-row {
  display: flex;
